cards=[]
cards.append(compact('bu_ping','布平','布平是云南出身的职业登山家，体型不高却结实，熟悉喜马拉雅山与欧洲山地，精通尼泊尔和西藏山区语言。他靠专业指导过着自在生活，也喜欢向朋友讲述自己的经历；当一个无法解答的问题困住自己时，这种豪爽会变成焦躁。《洞天》中，他因桑伯奇庙的怪石与失踪者而求助，随卫斯理、白素进入难以理解的感知环境，最终没有选择离开地球。到《生死锁》，他又为同业班德的坠落事件追索真相，亲赴现场切取岩石薄片，查明班德断绳是为避免拖累队友。在调查中他爱上班德的妻子丹妮，因此看见与班德同形的人时，既有职业求真的坚持，也有不愿伤害所爱之人的焦虑。最终得知班德精神已经离开、肉身由别人使用，布平才得以放下部分负担；他仍会问是否应向丹妮说一个安慰的版本。卡片保留登山技能和这种道德犹疑，不把结识天池老人或进入洞天算成他学会灵魂出窍。面对超常现象他可以诚实地不懂，却不应放弃以现场测量和实际行动帮助别人。','《生死锁》弄清班德事件并计划与丹妮继续生活；没有修得离体或脱离地球形态','重要配角','以专业本领对同行和所爱的人负责，也保留自己选择普通生活的自由','豪爽好谈山地，熟悉攀登、路线和山区语言','危机中依技能勘察救助，牵涉亲密关系时会迟疑甚至焦躁','无法理解超常机制时先查可靠物证，私人愿望不能代替事实',[ab('专业登山与山地调查','指导攀登、研究山形岩质和安全绳事故，能取样验证事故机制','仍受落差、岩石、天气和设备条件限制，非徒手攀登任何表面'),ab('山区语言与协调','掌握尼泊尔及西藏山区语言，熟悉寺院与登山活动往来','文化经验不等于掌握宗教神通')],[ev('061',81,106,'身份与专业'),ev('061',221,223,'山区语言'),ev('061',3320,3383,'未选择改变生命形态'),ev('070',3131,3219,'班德事故现场调查'),ev('070',3331,3348,'爱情与诚实的犹疑')],profile='investigator'))
cards.append(compact('li_yixin','李一心','李一心以李天范儿子的身体长大，瘦小而意志坚决，从小便有难以用家庭生活解释的倾向。他加入登山行动寻找一个自己也说不清的所在，不因体格遭讥笑便改变决定；后来在桑伯奇庙失踪，促使父亲与卫斯理等追查。终局他说明自己是来自另一星球的接引者，借用地球人的身体执行任务，肉身结构压抑了原有智能，所以多年只能模糊寻找，直到面对那块怪石才完全明白身份。怪石实际是交通与通讯工具，放出的能量使旁人误认石、山和身体大小，他负责接走长期发出离地愿望的贡云及摇铃大师。他愿向追索者解释，也容许他们拒绝改变生命形式，却以任务和原乡身份看待父亲的情感，认为自己只是寄居，不愿留下。卡片保留这种有礼但疏离的逻辑，不把接引者写成救济所有人的慈父，也不把机器制造的错觉误判成他任意缩放物质。终局已经完成接引离去，若再次参演须具体交代任务与工具可用条件；原生形态和星球整体技术没有被完整展示，不能补成无限宇宙权限。','《洞天》随接引工具带两位修行者离开地球；原生外星形态未详述','主角','完成接引任务并回归原属的生命形式','目的一贯而冷静，偏用自身尺度理解地球人的习惯','任务受阻时坚持寻找，身份恢复后直接说明不再承担地球家庭角色','接受或拒绝另一种生活应由当事者选择，工具效应不等于普遍自然规律',[ab('接引任务与思想信号辨识','按母星接收的长期思想信息寻找愿离地者，借人体行动后恢复身份认识','借人体时智能受限并长期迷惘，不能随时搜索所有人的想法'),ab('交通通讯工具协作','利用外观为石块的设备接引、通讯及改变现场感觉，最终带人离开','须有设备和任务条件；身体未实际缩小，未展示裸身任意星际移动')],[ev('061',913,935,'外形与寻找意志'),ev('061',3204,3288,'身份、肉身限制与工具'),ev('061',3289,3359,'接引原则、拒绝和离开')],profile='expert'))
rate(cards[-1],[1,4,3,5,7,3],neg=(2,2,1),tier='凶',reason='按本人可操作的接引通讯与感知工具计分；没有对外战争火力、现实缩放或宇宙范围任意权限。',mastery='基本掌握')
cards[-1]['baseline'].update({'durability':'地球寄居肉身的抗性未超出常人；返回后的原生身体未知，不能沿用想象中的无形无敌。','speed':'有接引交通工具可离地远行，肉身速度及航行耗时未给出。','energy':'设备能改变视觉等感觉并提供通讯交通，未展示等规模的攻击输出。','stamina':'地球肉身曾限制智能；返回后的生命规律未知，不赋予无限续航。'})
cards.append(compact('li_tianfan','李天范','李天范是享有声誉的天文学家，对星体及其相互作用有深入研究，平时应当有幽默感和从容学者气度。但在儿子李一心失踪后，他显得疲倦、苦涩而焦急，专业名望没有为他换来寻找孩子的捷径。他找到布平，希望借登山家的实际经验寻找失踪地点，又向卫斯理、白素叙述儿子自幼不同寻常的行为。那些在研究问题时可被当作观测对象的差异，落到父子关系里却是多年难以解开的牵挂。卫斯理等最后带回接引者与外星寄居的解释，他仍不断问一心去了哪里，认为儿子该回自己的家；这不是简单的科学无知，而是一个父亲难以接受被对方否认的亲情。终局没有让他与儿子重聚，也没有证实他能去那个星球寻找。他的卡片保留天文学知识和理性工作方法，同时容许他面对私人失落时不能立刻把逻辑接受转成情感接受。新的故事里，他可以继续提出清楚的问题、分析观测数据，也会把抽象“高等生命”的代价追问到具体家庭上；不因儿子是接引人而得到其外星技术或精神能力。','《洞天》获知儿子离地解释却难以接受，仍留地球；没有确认父子再见','主角','找回或理解儿子，并守住作为父亲的关系','有天文学专业与研究经验，日常可幽默而在求子时憔悴','亲人失踪使他放下名望求助，听到疏离的解释时激动反问','科学解释与情感接受是不同过程，不能以一个名词抹去真实亲情',[ab('天文学研究','具备星体研究和科学推理能力，能以专业知识讨论问题','学术权威不提供外星通讯、控星或找到所有失踪者的能力'),ab('家庭观察与求助','提供儿子自幼行为及失踪背景，主动联络可协助者','观察有父亲视角的局限，不能直接知道儿子的原生记忆')],[ev('061',1004,1063,'科学身份和求助'),ev('061',1106,1118,'儿子经过的叙述'),ev('061',3366,3375,'获知结果仍不能接受')],profile='expert'))
cards.append(compact('gong_yun','贡云大师','贡云大师是桑伯奇庙地位崇高的盲眼修行者，长年苦修，周围人惯于相信他不会弄错。他感到一个特殊来客已经到来，即使众人只发现一块石头，也坚持形体的差异不应妨碍理解；这一判断最终触及伪装为石的外星接引工具。他的威望使恩吉等人努力解释每句话，也可能令本来简单的实际行动变得拘谨。进入接引环境后，他以心念和所求解释自己所在，面对摇铃大师惊疑，温和指出对方过分执著位置。生来失明使他没有被石、山的视觉错觉左右，这是一种特殊处境带来的差异，而非对所有幻术无条件免疫。终局他接受李一心接引，离开地球原有的生命规律，具体之后的形态没有描述。卡片以最终选择和已展示的思想交流为基础，不把修成正果的宗教语言扩成全部佛法神通，也不假设赴另一星球后立即拥有当地一切技术。他的演绎可以安静而不僵硬，遇到执著术语的人用具体问题引导；真正重要的是他长期追求另一种生活，并愿意为这一选择告别熟悉的世界。','《洞天》接受接引离地，新的具体身体与能力未明；仅保留已展示的修行与思想感应','主角','摆脱固有生命规律，完成长期修行所指向的选择','沉静温和，重视心念而不执著表面形体','面对旁人惊疑时引导其辨别自己真正追求之事','直觉和思想感应须与所知边界并存，不把众人尊崇当作永不犯错',[ab('修行与思想感应','长期集中思想，感到接引来客并参与非口头信息联系','感应范围与稳定性未量化；不等于全知或操控所有人的意志'),ab('不受该视觉错觉影响','先天失明使其不随石山外观变化产生同样误认','只针对该视觉机制，不赋予对其他精神或信息攻击免疫')],[ev('061',460,542,'感知来客与威望'),ev('061',3113,3155,'引导摇铃大师'),ev('061',3287,3319,'失明与接引目标'),ev('061',3345,3359,'离去结果')],profile='expert'))
rate(cards[-1],[0,2,1,4,4,1],neg=(2,1,1),tier='并',reason='只计长期精神集中、有限感应与选择接引，不赋予离地后未知的成佛战力。')
