cards.append(compact('en_ji','恩吉','恩吉是桑伯奇庙实际处理事务的喇嘛，在庙中生活三十多年，熟悉每个院落，也深研佛理。他尊重贡云大师，面对院中突然出现的大石，既努力理解师长的话，又要处理如何把重物搬动的实际问题。他不是只会复述教义的人，愿意把布平等外人带入观察，希望不经意的机缘能帮助寺中解开谜题；同时他对灵界的解释十分笃定，容易把新现象纳入已有信仰。李一心、贡云和后来白素消失后，他感到某些传来的信息，却说不清具体位置和机制，因而既敬畏又担心无法向家属交代。他最终同意卫斯理按自己的方法留在禅房调查，表现出信仰之外仍有合作和承担的余地。终局接引工具带人离去，恩吉并不是明确被带走的成员，不能把师长的新生命形式移植给他。卡片保留寺院管理、佛理思考与有限思想交流，不附会搬山、瞬移或强制渡人。他在新环境中会先维护修行者和访客的秩序，见到不同方法有效时也可以让步，而非永远用机锋拒绝回答。','《洞天》留在寺院，接引者及两位大师离开；本人没有确认离地或获得新形态','主角','维护寺院与修行秩序，理解神秘来客并向有关者交代','尊师、勤思，也愿接待外人帮助研究','接连失踪使他忧虑，仍努力接收信息并安排调查','宗教解释可以指导自己，但实际未知仍应向求助者说明',[ab('寺院事务与佛理','长期管理寺院、熟悉环境并组织接待和研究','地位不代表拥有其他喇嘛所有能力'),ab('有限传心感应','在相关事件中感到他人传来的信息，尝试集中精神回应','信息不完整，不能定位所有失踪者或随意读心')],[ev('061',318,346,'住持身份及研究'),ev('061',483,538,'处理大石与师长'),ev('061',2769,2832,'感应、忧虑及允许调查')],profile='expert'))
rate(cards[-1],[1,1,1,2,2,2],neg=(1,2,1),tier='并',reason='以有限信息感应和寺院组织经验计分，非成熟的战斗精神术。')
cards.append(compact('bell_lama','摇铃大师','摇铃大师是参与桑伯奇庙神秘事件的修行者，以手中铜铃和与贡云的对话被辨认，原文没有给出可进一步核定的姓名。他经过数十年的思考训练，对修行术语很熟悉，但当自己真正处在无法辨明的位置时，仍会惊慌、急促呼吸，并追问是否已经到了灵界。这份反应使他并非一尊只会说偈语的塑像：平常可以理解的道理，在切身失去熟悉参照后仍需要重新接受。贡云提醒他不要只牵挂身在何处，他经历短暂惘然后重新微笑，认可自己已经接近一直追求的境地。终局他与贡云一同接受李一心接引，离开地球原有生活，而新的具体能力并没有展开。铜铃在现场用于其个人行动与表达，不是经证实的音波兵器，也不能因被称大师就拥有全部宗教神通。卡片保留长期修行、能从震动中恢复理解以及自愿离地的选择；若在另一场景遭遇真正未知，他仍可先害怕、再问、再作决定，不必永远从容到丧失人物性。','《洞天》与贡云接受接引离地，姓名和之后的新生命形态未明','主角','完成长期修行所追求的脱离旧有生命方式','以铜铃伴随修行，善思却仍需要实际理解陌生处境','真正进入未知时惊疑，经过提示能反省并恢复平静','理解术语不能替代亲身选择，所求之境也须由自己确认',[ab('长期精神修习','具有多年集中思考与修行经验，能在惊疑后重新理解并作选择','没有直接攻击或强制精神控制展示；铜铃不作为魔法武器')],[ev('061',3120,3155,'惊疑、对答与反省'),ev('061',3221,3234,'接引目标'),ev('061',3345,3359,'随接引离去')],profile='expert'))
save(cards)
cover('061',[('卫斯理','wei_sili','主角','追查失踪并经历接引空间'),('白素','bai_su','主角','独立追踪、提问和选择留地'),('布平','bu_ping','重要配角','山地专家与线索提供者'),('李一心','li_yixin','主角','接引者'),('李天范','li_tianfan','主角','失子父亲与科学家'),('贡云','gong_yun','主角','被接引的修行者'),('恩吉','en_ji','主角','主持寺院调查'),('摇铃大师','bell_lama','主角','有独立对话与最终接引选择')],[('其他上师和登山队员','未提供足以区分的个人身份或独立反派行动，不拆成虚构单人')],['石块是感知伪装的交通通讯工具；正文明确身体没有缩小，不给任何人现实大小改写。'])
